__global__ void matmul_optimized_kernel(const float* __restrict__ A, 
                                         const float* __restrict__ B, 
                                         float* __restrict__ C,
                                         int M, int K, int N) {
    // Shared memory tiles
    __shared__ float As[BK][BM];  // Transposed for better access
    __shared__ float Bs[BK][BN];

